                if computed != *group {
                    return Err(PalwStateV2Error::ChunkGroupHashMismatch { group: *group, computed });
                }
                let inner: PalwConsensusObjectV2 =
                    borsh::from_slice(&whole).map_err(|e| PalwStateV2Error::ChunkedObjectUndecodable(e.to_string()))?;
